#!/bin/sh
# SkyWater 130 nm HD standard cells (typical corner: tt, 25 C, 1.8 V) for api/routes/asic.py.
# The liberty file is pinned to an OpenROAD-flow-scripts commit and checked against its sha256.
# cells.v: a Verilog model of every cell, generated by Yosys from the cell functions in that
# same library, for gate-level simulation. Used by Dockerfile.api and the CI ASIC job.
set -eu
DEST=${1:-/opt/sky130}
ORFS=3ff0197f070c65f2dd8ec10b06d1fdcb3bc3c993
LIB=sky130_fd_sc_hd__tt_025C_1v80.lib
SHA256=ec0e1067a35c8bf20b11e58d1e8ac53326067e4dac84a125cc1b917a3518d0d9

mkdir -p "$DEST"
curl -fsSL -o "$DEST/$LIB" \
  "https://raw.githubusercontent.com/The-OpenROAD-Project/OpenROAD-flow-scripts/$ORFS/flow/platforms/sky130hd/lib/$LIB"
echo "$SHA256  $DEST/$LIB" | sha256sum -c -
yosys -q -p "read_liberty -ignore_miss_func -ignore_miss_dir $DEST/$LIB; write_verilog -noattr $DEST/cells.v"
chmod 644 "$DEST"/*
